{
  "schema_version": 1,
  "observations": [
    {
      "key": "obs_1",
      "facet": "reference",
      "statement": "A priority queue is a common use for a heap.",
      "start_line": 1,
      "end_line": 1
    },
    {
      "key": "obs_2",
      "facet": "precondition",
      "statement": "To return tasks with equal priorities in the order they were originally added, a mechanism for ordering equal-priority items is required.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_3",
      "facet": "property",
      "statement": "Tuple comparison breaks for (priority, task) pairs if the priorities are equal and the tasks do not have a default comparison order.",
      "start_line": 5,
      "end_line": 5
    },
    {
      "key": "obs_4",
      "facet": "mechanism",
      "statement": "If the priority of a task changes, it must be moved to a new position in the heap.",
      "start_line": 7,
      "end_line": 7
    },
    {
      "key": "obs_5",
      "facet": "mechanism",
      "statement": "If a pending task needs to be deleted, it must be found and removed from the queue.",
      "start_line": 7,
      "end_line": 7
    },
    {
      "key": "obs_6",
      "facet": "mechanism",
      "statement": "A solution to the first two challenges is to store priority, an entry count, and the task.",
      "start_line": 9,
      "end_line": 9
    },
    {
      "key": "obs_7",
      "facet": "property",
      "statement": "The entry count serves as a tie-breaker.",
      "start_line": 9,
      "end_line": 9
    },
    {
      "key": "obs_8",
      "facet": "property",
      "statement": "The entry count prevents tuple comparison from directly comparing tasks.",
      "start_line": 9,
      "end_line": 9
    }
  ],
  "claims": [],
  "questions": []
}
